// pfsLogoBase64.js - PFS PrimaryLogo Navy Horizontal transparent PNG,
// downsampled to 400x129 (~2x for the 132px display) and embedded as
// base64. Chosen resolution: comfortably 2x for Retina/print, ~4.5x
// smaller than the 1036x336 source, permanent reduction of ~160KB per
// confirmation email attachment.
//
// Downsample done via `sips -Z 400` (macOS bicubic) from the source
// PFS_PrimaryLogo_Navy_Horizontal_transparent.png that Kevin supplied
// 2026-09-09. Source alpha edges (hard threshold knockout) survive
// the resample cleanly; letterforms verified in mount-verify PDFs.
//
// If PFS reissues the mark, re-run:
//   sips -Z 400 <new-source>.png --out /tmp/pfs_logo_400.png
//   base64 -i /tmp/pfs_logo_400.png -o /tmp/pfs_logo_400.b64
// then replace the string below with the new base64.

export const PFS_LOGO_PNG_BASE64 = "";
